CREATE TABLE oauth_clients(client_id TEXT PRIMARY KEY, name TEXT NOT NULL, secret_hash TEXT, redirect_uris TEXT NOT NULL DEFAULT '[]', grant_types TEXT NOT NULL, scope TEXT NOT NULL, auth_method TEXT NOT NULL, software TEXT, uri TEXT, created INTEGER NOT NULL) /* RFC 7591 dynamic client registration; secret_hash NULL means a public client authenticated only by PKCE */;
CREATE TABLE oauth_pending(id TEXT PRIMARY KEY, client_id TEXT NOT NULL, subject TEXT NOT NULL, redirect_uri TEXT NOT NULL, scope TEXT NOT NULL, state TEXT, challenge TEXT NOT NULL, resource TEXT, csrf_hash TEXT NOT NULL, expires INTEGER NOT NULL, created INTEGER NOT NULL) /* one authorization request awaiting consent; csrf_hash is the hash of the value also set as a cookie */;
CREATE INDEX oauth_pending_expiry ON oauth_pending(expires);
CREATE TABLE oauth_codes(hash TEXT PRIMARY KEY, client_id TEXT NOT NULL, grant_id TEXT NOT NULL, subject TEXT NOT NULL, tenant TEXT NOT NULL, scope TEXT NOT NULL, redirect_uri TEXT NOT NULL, challenge TEXT NOT NULL, resource TEXT, expires INTEGER NOT NULL, created INTEGER NOT NULL) /* single-use authorization codes, hashed at rest, bound to client, redirect URI and PKCE challenge */;
CREATE INDEX oauth_codes_expiry ON oauth_codes(expires);
CREATE TABLE oauth_grants(id TEXT PRIMARY KEY, client_id TEXT NOT NULL, subject TEXT NOT NULL, tenant TEXT NOT NULL, scope TEXT NOT NULL, created INTEGER NOT NULL, revoked INTEGER) /* one consent; revoking it kills every token descended from it */;
CREATE INDEX oauth_grants_subject ON oauth_grants(subject);
CREATE TABLE oauth_tokens(hash TEXT PRIMARY KEY, id TEXT NOT NULL, kind TEXT NOT NULL, grant_id TEXT NOT NULL, client_id TEXT NOT NULL, subject TEXT NOT NULL, tenant TEXT NOT NULL, scope TEXT NOT NULL, expires INTEGER NOT NULL, created INTEGER NOT NULL, used INTEGER) /* access and refresh tokens, SHA-256 hashed; used marks a rotated refresh token kept for reuse detection */;
CREATE INDEX oauth_tokens_grant ON oauth_tokens(grant_id);
CREATE INDEX oauth_tokens_expiry ON oauth_tokens(expires);
CREATE TABLE oauth_devices(hash TEXT PRIMARY KEY, user_code TEXT NOT NULL UNIQUE, client_id TEXT NOT NULL, scope TEXT NOT NULL, status TEXT NOT NULL, subject TEXT, tenant TEXT, grant_id TEXT, interval INTEGER NOT NULL, polled INTEGER NOT NULL DEFAULT 0, expires INTEGER NOT NULL, created INTEGER NOT NULL) /* RFC 8628 device authorization; status is pending, approved or denied */;
CREATE INDEX oauth_devices_expiry ON oauth_devices(expires);
CREATE TABLE oauth_rate(key TEXT PRIMARY KEY, window INTEGER NOT NULL, count INTEGER NOT NULL) /* fixed-window counters for the token, device and registration endpoints */;
CREATE INDEX oauth_rate_window ON oauth_rate(window);
INSERT OR IGNORE INTO oauth_clients(client_id,name,secret_hash,redirect_uris,grant_types,scope,auth_method,software,uri,created) VALUES('caelogram-cli','Caelogram CLI',NULL,'[]','["urn:ietf:params:oauth:grant-type:device_code","refresh_token"]','read write publish admin','none','caelogram-cli',NULL,0);
